/bin/bash -lc "python3 - <<'PY'
import gzip
markers=['CD3D','CD14','MS4A1','NKG7','PPBP','FCGR3A','CD8A','CD4','GNLY','LYZ','HBB','HBA1','S100A8','IGKC','MZB1','IL7R','CCR7','TCL1A','CD79A','CST3','LILRA4','CLEC4C']
D={}
with gzip.open('inputs/multiome.match.atac.rna.q1.rna.tsv.gz','rt') as f:
    h=f.readline().strip().split('\\t')
    for line in f:
        p=line.strip().split('\\t')
        if p[0] in markers:
            D[p[0]]=[float(x) for x in p[1:]]
for g in markers:
    if g in D:
        print(g, ['%.2f'%v for v in D[g]])
PY"

